const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');

const { FIXTURES_ROOT, withServer } = require('./helpers.js');

const LEVELS_FIXTURES = path.join(FIXTURES_ROOT, 'levels');
const JSON_CONTENT_TYPE = 'application/json; charset=utf-8';

async function assertLevelDataUnavailable(t, dataPath) {
  await withServer(t, { dataPath }, async (instance) => {
    const response = await fetch(`${instance.origin}/api/levels`);

    assert.equal(response.status, 500);
    assert.equal(response.headers.get('content-type'), JSON_CONTENT_TYPE);

    const body = await response.json();
    assert.equal(body.error.code, 'LEVEL_DATA_UNAVAILABLE');
    assert.equal(typeof body.error.message, 'string');
    assert.ok(body.error.message.length > 0);
    assert.ok(!body.error.message.includes(path.sep));
    assert.ok(!body.error.message.includes('    at '));
    assert.ok(!body.error.message.includes(dataPath));
  });
}

for (const failureCase of [
  { name: '数据文件缺失', dataPath: path.join(LEVELS_FIXTURES, 'missing.json') },
  { name: 'JSON 解析失败', dataPath: path.join(LEVELS_FIXTURES, 'malformed.json') },
  { name: '顶层不是数组', dataPath: path.join(LEVELS_FIXTURES, 'not-array.json') },
  { name: '关卡结构校验失败', dataPath: path.join(LEVELS_FIXTURES, 'invalid-structure.json') },
  { name: '关卡数量不是 5', dataPath: path.join(LEVELS_FIXTURES, 'wrong-length.json') },
]) {
  test(`AC-002: ${failureCase.name}时返回 500 LEVEL_DATA_UNAVAILABLE`, async (t) => {
    await assertLevelDataUnavailable(t, failureCase.dataPath);
  });
}

test('AC-002: 数据文件不可读时返回 500 LEVEL_DATA_UNAVAILABLE', async (t) => {
  const unreadablePath = path.join(LEVELS_FIXTURES, 'unreadable.json');
  await fs.writeFile(unreadablePath, '[]', 'utf8');
  await fs.chmod(unreadablePath, 0o000);

  try {
    await assertLevelDataUnavailable(t, unreadablePath);
  } finally {
    await fs.chmod(unreadablePath, 0o644);
    await fs.rm(unreadablePath, { force: true });
  }
});
