const test = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');

const { STATIC_ROOT, withServer } = require('./helpers.js');

function rawRequest(instance, requestPath) {
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        host: '127.0.0.1',
        port: instance.port,
        path: requestPath,
        method: 'GET',
      },
      (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => {
          body += chunk;
        });
        res.on('end', () => resolve({ status: res.statusCode, body }));
      },
    );
    req.on('error', reject);
    req.end();
  });
}

test('AC-004: GET / 返回 staticRoot 下的页面 HTML', async (t) => {
