const { withServer } = require('./helpers.js');

const JSON_CONTENT_TYPE = 'application/json; charset=utf-8';
const VALID_DIFFICULTIES = ['简单', '普通', '困难'];

test('AC-001: GET /api/levels 返回 200 与恰好 5 个合法关卡', async (t) => {
  await withServer(t, {}, async (instance) => {
    const response = await fetch(`${instance.origin}/api/levels`);

    assert.equal(response.status, 200);
    assert.equal(response.headers.get('content-type'), JSON_CONTENT_TYPE);

    const levels = await response.json();
    assert.ok(Array.isArray(levels));
    assert.equal(levels.length, 5);

    const ids = new Set();
    for (const level of levels) {
      assert.equal(typeof level.id, 'string');
      assert.ok(level.id.trim().length > 0);
      assert.ok(!ids.has(level.id));
      ids.add(level.id);

      assert.equal(typeof level.name, 'string');
      assert.ok(level.name.trim().length > 0);

      assert.ok(VALID_DIFFICULTIES.includes(level.difficulty));
      assert.equal(typeof level.unlocked, 'boolean');
    }
    assert.equal(ids.size, 5);
  });
});

