const LEVEL_DATA_ERROR_MESSAGE = '关卡数据不可用，请稍后重试';

const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

class LevelDataError extends Error {}

function resolvePort(explicitPort) {
  if (explicitPort !== undefined) {
    return explicitPort;
  }
  const envPort = Number(process.env.PORT);
  if (Number.isInteger(envPort) && envPort >= 0) {
    return envPort;
  }
  return DEFAULT_PORT;
}

function defaultDataPath() {
  return path.join(__dirname, '..', 'data', 'levels.json');
}

function defaultStaticRoot() {
  return path.join(__dirname, '..', 'web');
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function sendJson(res, statusCode, payload, extraHeaders = {}) {
  const body = JSON.stringify(payload);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    ...extraHeaders,
  });
  res.end(body);
}

function sendText(res, statusCode, body = 'Not Found') {
  res.writeHead(statusCode, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function validateLevels(raw) {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new LevelDataError('关卡数据不是有效的 JSON');
  }
  if (!Array.isArray(parsed)) {
    throw new LevelDataError('关卡数据顶层必须是数组');
  }
  if (parsed.length !== REQUIRED_LEVEL_COUNT) {
    throw new LevelDataError(`关卡数据必须包含 ${REQUIRED_LEVEL_COUNT} 个关卡`);
  }

  const seenIds = new Set();
  parsed.forEach((level, index) => {
    const position = `第 ${index + 1} 个关卡`;
    if (!isPlainObject(level)) {
      throw new LevelDataError(`${position}必须是对象`);
    }
    if (typeof level.id !== 'string' || level.id.trim() === '') {
      throw new LevelDataError(`${position}的 id 必须是非空字符串`);
    }
    if (seenIds.has(level.id)) {
      throw new LevelDataError(`${position}的 id 在文件内重复`);
    }
    seenIds.add(level.id);
    if (typeof level.name !== 'string' || level.name.trim() === '') {
      throw new LevelDataError(`${position}的 name 必须是非空字符串`);
    }
    if (!VALID_DIFFICULTIES.includes(level.difficulty)) {
      throw new LevelDataError(`${position}的 difficulty 必须是简单、普通或困难`);
    }
    if (typeof level.unlocked !== 'boolean') {
      throw new LevelDataError(`${position}的 unlocked 必须是布尔值`);
    }
  });
  return parsed;
}

async function loadLevels(dataPath) {
  let raw;
  try {
    raw = await fs.readFile(dataPath, 'utf8');
  } catch {
    throw new LevelDataError('关卡数据文件缺失或不可读');
  }
  return validateLevels(raw);
}

async function sendLevels(res, dataPath) {
  try {
    const levels = await loadLevels(dataPath);
    sendJson(res, 200, levels);
  } catch (error) {
    if (!(error instanceof LevelDataError)) {
      throw error;
    }
    sendJson(res, 500, {
      error: {
        code: LEVEL_DATA_ERROR_CODE,
        message: LEVEL_DATA_ERROR_MESSAGE,
      },
    });
  }
}

async function serveStatic(req, res, staticRoot, pathname) {
  if (req.method !== 'GET') {
    sendText(res, 404);
    return;
  }

  let decoded;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    sendText(res, 404);
    return;
  }
  if (decoded.includes('\0')) {
    sendText(res, 404);
    return;
  }

  let target = path.resolve(staticRoot, decoded.replace(/^\/+/, ''));
  if (target !== staticRoot && !target.startsWith(staticRoot + path.sep)) {
    sendText(res, 404);
    return;
  }

  let stat = await fs.stat(target).catch(() => null);
  if (stat !== null && stat.isDirectory()) {
    target = path.join(target, 'index.html');
    stat = await fs.stat(target).catch(() => null);
  }
  if (stat === null || !stat.isFile()) {
    sendText(res, 404);
    return;
  }

  try {
    const content = await fs.readFile(target);
    res.writeHead(200, {
      'Content-Type': CONTENT_TYPES[path.extname(target).toLowerCase()] ?? 'application/octet-stream',
      'Content-Length': content.length,
    });
    res.end(content);
  } catch {
    if (!res.headersSent) {
      sendText(res, 404);
    } else {
      res.destroy();
    }
  }
}

async function routeRequest(req, res, options) {
  let pathname = '/';
  try {
    pathname = new URL(req.url ?? '/', 'http://127.0.0.1').pathname;
  } catch {
    sendText(res, 404);
    return;
  }

  if (pathname === API_LEVELS_PATH) {
    if (req.method !== 'GET') {
      sendJson(
        res,
        405,
        {
          error: {
            code: 'METHOD_NOT_ALLOWED',
            message: '不支持的请求方法',
          },
        },
        { Allow: 'GET' },
      );
      return;
    }
    await sendLevels(res, options.dataPath);
    return;
  }
  if (pathname === '/api' || pathname.startsWith('/api/')) {
    sendJson(res, 404, {
      error: {
        code: 'NOT_FOUND',
        message: '接口不存在',
      },
    });
    return;
  }
  await serveStatic(req, res, options.staticRoot, pathname);
}

function createServer(options = {}) {
  const dataPath = options.dataPath ?? defaultDataPath();
  const staticRoot = path.resolve(options.staticRoot ?? defaultStaticRoot());
  const handleRequest = async (req, res) => {
    try {
      await routeRequest(req, res, { dataPath, staticRoot });
    } catch {
      if (!res.headersSent) {
        sendJson(res, 500, {
          error: {
            code: 'INTERNAL_ERROR',
            message: '服务器内部错误',
          },
        });
      } else {
        res.destroy();
      }
    }
  };
  return http.createServer(handleRequest);
}

function start(options = {}) {
  const server = createServer(options);
  const port = resolvePort(options.port);

  const stop = () =>
    new Promise((resolveStop) => {
      if (!server.listening) {
        resolveStop();
        return;
      }
      if (typeof server.closeIdleConnections === 'function') {
        server.closeIdleConnections();
      }
      server.close(() => resolveStop());
    });

  return new Promise((resolve, reject) => {
    const onListenError = (error) => {
      reject(error);
    };
    server.once('error', onListenError);
    server.listen(port, () => {
      server.off('error', onListenError);
      const address = server.address();
      const boundPort = isPlainObject(address) ? address.port : port;
      resolve({
        origin: `http://127.0.0.1:${boundPort}`,
        port: boundPort,
        stop,
      });
    });
  });
}

module.exports = { createServer, start };
